command:
if (!game.user.isGM) return ui.notifications.warn('Clear Terrain Effects is GM-only.');

const map = canvas.scene;
if (!map) return ui.notifications.warn('No map is active.');

const result = await game.emblemRpg.api.development.clearTerrainEffects({ sceneUuid: map.uuid });
console.group(`emblem-rpg | Clear Terrain Effects — ${map.name}`);
console.log(result.ok ? result.data : result);
console.groupEnd();
